                    "INSERT INTO machine_keys"
                    "(machine_id, version, public_key, activated_at_ms, revoked)"
                    " VALUES (?, 1, ?, 0, 0)",
                    (machine_id, public_key),
                )
                database.execute(
                    "INSERT INTO idempotency_records(key, machine_id, public_key) VALUES (?, ?, ?)",
                    (idempotency_key, machine_id, public_key),
