from __future__ import annotations

import json
import tempfile
import threading
import time
from pathlib import Path
from urllib.error import HTTPError
from urllib.request import Request, urlopen

from sla_network.server import ApiServer, Handler
import sys

sys.path.insert(0, "tests")
from test_server import (  # noqa: E402
    PUBLIC_KEY_A, machine_id, make_sla_auth, PRODUCER_SEED, DELEGATE_PUBLIC,
)

tmp = tempfile.TemporaryDirectory()
server = ApiServer(("127.0.0.1", 0), Handler)
server.database_path = str(Path(tmp.name) / "service.db")
threading.Thread(target=server.serve_forever, daemon=True).start()
producer = machine_id(PUBLIC_KEY_A)
base = f"http://127.0.0.1:{server.server_port}"


def call(method, path, body=b"", headers=None):
    req = Request(base + path, data=body if method == "POST" else None, method=method)
    for k, v in (headers or {}).items():
        req.add_header(k, v)
    try:
        with urlopen(req, timeout=5) as r:
            return r.status, r.read()
    except HTTPError as e:
        return e.code, e.read()


call(
    "POST", "/v1/machines",
    json.dumps({"publicKey": PUBLIC_KEY_A}).encode(), {"Idempotency-Key": "r1"},
)
expires = int(time.time() * 1000) + 3_600_000
for i in (1, 2):
    body = json.dumps(
        {"id": f"del-{i}", "delegatePublicKey": DELEGATE_PUBLIC, "expiresAt": expires}
    ).encode()
    h = {
        "Idempotency-Key": f"i{i}",
        "SLA-Auth": make_sla_auth(
            server, f"i{i}", PRODUCER_SEED, producer,
            "POST", "/v1/delegations", body, 1,
        ),
    }
    print("issue", i, call("POST", "/v1/delegations", body, h))

lp = f"/v1/machines/{producer}/delegations"
h = {
    "SLA-Auth": make_sla_auth(
        server, "k1", PRODUCER_SEED, producer,
        "GET", "/v1/delegations/del-1/events", b"", 1,
    )
}
print(
    "cross-delegation anchor:",
    call("GET", "/v1/delegations/del-1/events?cursor=2:2", b"", h),
)
stale = int(time.time() * 1000) - 400_000
h1 = {
    "SLA-Auth": make_sla_auth(
        server, "x1", PRODUCER_SEED, producer, "GET", lp, b"", 1,
        request_time_ms=stale, nonce="nonce-stale-x001",
    )
}
print("stale:", call("GET", lp, b"", h1))
h2 = {
    "SLA-Auth": make_sla_auth(
        server, "x1", PRODUCER_SEED, producer, "GET", lp, b"", 1,
        nonce="nonce-stale-x001",
    )
}
print("reuse after fail:", call("GET", lp, b"", h2))
h3 = {
    "SLA-Auth": make_sla_auth(
        server, "x2", PRODUCER_SEED, producer, "GET", lp, b"", 1,
        nonce="nonce-stale-x001",
    )
}
print("same nonce again now replay:", call("GET", lp, b"", h3))
server.shutdown()
tmp.cleanup()

